<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);require dirname(__DIR__).'/src/bootstrap.php';
try{
 $source=$argv[1]??'';if(!in_array('--reference-catalog-only',$argv,true)||!is_file($source))throw new RuntimeException('Supply a reviewed SQLite reference copy and --reference-catalog-only. This creates a clean catalog release, never a live-history migration.');
 $dir=ANNAM_ROOT.'/build/local';if(!is_dir($dir))mkdir($dir,0700,true);$file=$dir.'/annam.sqlite';if(is_file($file))unlink($file);$db=new PDO('sqlite:'.$file,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);chmod($file,0600);$db->exec(file_get_contents(ANNAM_ROOT.'/resources/sqlite-schema.sql'));$db->exec('PRAGMA foreign_keys=OFF');$input=new PDO('sqlite:'.$source,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$types=json_decode(file_get_contents(ANNAM_ROOT.'/resources/sqlite-types.json'),true);
 $keep=['tenancy_tenant','tenancy_tenantconfig','tenancy_billingprofile','catalog_slot','catalog_menucategory','catalog_menuitem','catalog_menuschedule','catalog_menuday','catalog_catalogsyncrun','delivery_deliveryzone','content_page','content_banner','content_storefrontimage'];
 $db->beginTransaction();foreach($keep as $table){if(!$input->query("SELECT name FROM sqlite_master WHERE type='table' AND name=".$input->quote($table))->fetch())continue;$fields=$types[$table];foreach($input->query('SELECT * FROM "'.$table.'"',PDO::FETCH_ASSOC) as $row){$names=array_values(array_intersect(array_keys($row),array_keys($fields)));$statement=$db->prepare('INSERT INTO "'.$table.'" ('.implode(',',array_map(fn($n)=>'"'.$n.'"',$names)).') VALUES('.implode(',',array_fill(0,count($names),'?')).')');foreach($names as $i=>$name){$value=$row[$name];if($value!==null&&$fields[$name]==='DECIMAL_TEXT')$value=Annam\Money::decimal(Annam\Money::parse((string)$value));if($value!==null&&$fields[$name]==='TIMESTAMP')$value=Annam\SqliteDialect::timestamp($value);$statement->bindValue($i+1,$value,$value===null?PDO::PARAM_NULL:($fields[$name]==='BLOB'?PDO::PARAM_LOB:(is_int($value)?PDO::PARAM_INT:PDO::PARAM_STR)));}$statement->execute();}}
 $tenant=$db->query("SELECT id FROM tenancy_tenant WHERE slug='annam'")->fetchColumn();if(!$tenant)throw new RuntimeException('The Annam catalog is missing.');
 // Reset test counters; do not invent current menus from dated category names.
 $db->exec('UPDATE catalog_menuschedule SET qty_sold=0');$row=$db->query('SELECT theme,features,checkout_settings FROM tenancy_tenantconfig WHERE tenant_id='.(int)$tenant)->fetch(PDO::FETCH_ASSOC);$theme=json_decode($row['theme'],true);$theme['logo_url']='/media/brand/annam-logo.png';$theme['billing_logo_url']='/media/brand/annam-bill-logo.png';$features=json_decode($row['features'],true);$features['manual_payments']=true;$features['website_ordering']=true;$features['snacks_courier']=true;$settings=json_decode($row['checkout_settings'],true);$settings['courier_enabled']=true;$settings['courier_fee']='0.00';$settings['courier_minimum']=$settings['courier_minimum']??'0.00';$settings['courier_notifications_enabled']=false;$settings['courier_online_enabled']=false;$settings['courier_pincodes']=[];$settings['payment_instructions']=$settings['payment_instructions']??'Please contact the kitchen to arrange payment.';
 $db->prepare('UPDATE tenancy_tenantconfig SET theme=?,features=?,checkout_settings=? WHERE tenant_id=?')->execute([json_encode($theme),json_encode($features),json_encode($settings),$tenant]);$db->commit();Annam\PublicMedia::apply($db,dirname(ANNAM_ROOT).'/media');$db->exec('PRAGMA foreign_keys=ON');if($db->query('PRAGMA foreign_key_check')->fetch()||$db->query('PRAGMA integrity_check')->fetchColumn()!=='ok')throw new RuntimeException('Catalog release integrity failed.');
 $counts=[];foreach(['catalog_menuitem','catalog_menucategory','delivery_deliveryzone','orders_order','auth_user'] as $table)$counts[$table]=(int)$db->query('SELECT COUNT(*) FROM '.$table)->fetchColumn();$report=['contents'=>'Reviewed local reference catalog/settings. No live Supabase history, customer records, test orders, login passwords or integration credentials.','counts'=>$counts,'public_media'=>Annam\PublicMedia::summary(Annam\PublicMedia::inventory(),dirname(ANNAM_ROOT).'/media'),'catalog_items_with_photos'=>(int)$db->query("SELECT COUNT(*) FROM catalog_menuitem WHERE image<>''")->fetchColumn(),'original_product_photos'=>'Only checksum-verified downloaded originals are assigned. Pending/unavailable source photos remain unassigned; see public-media.json.'];file_put_contents($dir.'/DATA-INCLUDED.json',json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));echo json_encode($report,JSON_PRETTY_PRINT).PHP_EOL;
}catch(Throwable $e){fwrite(STDERR,'Local release preparation failed: '.$e->getMessage().PHP_EOL);exit(1);}
